import type { Instant } from "@/lib/time"
import type { Tone } from "@/lib/tone"

type CommitStatus = "pending" | "done"

/** A piece of a commit message: plain text, a file path or a branch name (shown as chips), or inline code. */
type CommitMessageSegment =
  | { type: "text"; text: string }
  | { type: "file"; path: string }
  | { type: "branch"; name: string }
  | { type: "code"; text: string }

type CommitTag = { label: string; tone?: Tone }

type CommitAuthor = string | { name: string; email?: string }

type CommitStats = { files: number; additions: number; deletions: number }

type Commit = {
  /** The full hash, or any id unique in the history. */
  id: string
  /** Parent ids, first parent first, as `git log --format=%P` gives them. */
  parents: readonly string[]
  /** A string (backticked paths and `branch:` names become chips) or segments. */
  message: string | readonly CommitMessageSegment[]
  date: Instant
  author?: CommitAuthor
  /** The hash people read and copy; the first 7 characters of `id` by default. */
  hash?: string
  /** The rest of the message, after its subject line. */
  body?: string
  tags?: readonly CommitTag[]
  stats?: CommitStats
  /** `"pending"` while the commit is being written: a spinning node and a status in place of the time. */
  status?: CommitStatus
}

/**
 * The commits in order, with each one's place in the "one line per commit" trail. A merge's merged-in branch
 * nests under it: the commits right after the merge that only it reaches, the way `git log --graph --topo-order`
 * prints them. Rows keep the order they arrived in, so nesting never reorders history.
 */
type CommitGraph = {
  readonly commits: readonly Commit[]
  readonly rowOf: ReadonlyMap<string, number>
  /** 0 on the mainline, 1 for a merged branch's commits, 2 for a branch merged into that one… */
  readonly depth: Int32Array
  /** The merge a row nests under, or -1 on the top level. */
  readonly owner: Int32Array
  /** One past the last row nested under a row, at any depth; `row + 1` for a row with none. */
  readonly end: Int32Array
  /** How many rows nest directly under a row. */
  readonly children: Int32Array
  readonly size: number
}

type Claim = { owner: number; depth: number; first: boolean }

type NestState = { claims: Map<string, Claim>; stack: number[] }

const graphState = new WeakMap<CommitGraph, NestState>()

function better(next: Claim, current: Claim | undefined) {
  if (!current) return true
  if (next.depth !== current.depth) return next.depth < current.depth
  return next.first && !current.first
}

function grow(array: Int32Array, size: number) {
  if (array.length >= size) return array
  const next = new Int32Array(Math.max(size, array.length * 2, 64))
  next.set(array)
  return next
}

function nest(graph: CommitGraph, state: NestState, from: number): CommitGraph {
  const { commits } = graph
  const size = commits.length
  const depth = grow(graph.depth, size)
  const owner = grow(graph.owner, size)
  const end = grow(graph.end, size)
  const children = grow(graph.children, size)
  const rowOf = graph.rowOf as Map<string, number>
  const { claims, stack } = state
  for (let row = from; row < size; row += 1) {
    const commit = commits[row] as Commit
    rowOf.set(commit.id, row)
    const claim = claims.get(commit.id)
    claims.delete(commit.id)
    let parent = -1
    if (claim && claim.owner >= 0) {
      const at = stack.lastIndexOf(claim.owner)
      // A merged branch shows as one block under its merge; once the mainline moves on, a late commit of it
      // can't join the block, so it falls back to the top level.
      if (at >= 0) {
        stack.length = at + 1
        parent = claim.owner
      } else stack.length = 0
    } else stack.length = 0
    owner[row] = parent
    depth[row] = parent < 0 ? 0 : (depth[parent] as number) + 1
    end[row] = row + 1
    children[row] = 0
    if (parent >= 0) children[parent] = (children[parent] as number) + 1
    for (let ancestor = parent; ancestor >= 0; ancestor = owner[ancestor] as number) end[ancestor] = row + 1
    const parents = commit.parents
    const own = depth[row] as number
    for (let index = 0; index < parents.length; index += 1) {
      const id = parents[index] as string
      const placed = rowOf.get(id)
      if (placed !== undefined && placed < row && commits[placed]?.id === id) continue
      const next: Claim =
        index === 0 ? { owner: parent, depth: own, first: true } : { owner: row, depth: own + 1, first: false }
      if (better(next, claims.get(id))) claims.set(id, next)
    }
    if (parents.length > 1) stack.push(row)
  }
  const next: CommitGraph = { commits, rowOf, depth, owner, end, children, size }
  graphState.set(next, state)
  return next
}

/** Builds the trail's structure in one pass over the commits, children before parents (`git log` order). */
function createCommitGraph(commits: readonly Commit[]): CommitGraph {
  const empty: CommitGraph = {
    commits,
    rowOf: new Map(),
    depth: new Int32Array(0),
    owner: new Int32Array(0),
    end: new Int32Array(0),
    children: new Int32Array(0),
    size: 0,
  }
  return nest(empty, { claims: new Map(), stack: [] }, 0)
}

function sameShape(a: Commit, b: Commit) {
  if (a === b) return true
  if (a.id !== b.id || a.parents.length !== b.parents.length) return false
  return a.parents.every((parent, index) => parent === b.parents[index])
}

/**
 * The graph for `commits`, reusing `previous` when the history only grew at the end (an older page) or only
 * changed commits' content (a pending commit that finished): O(new rows) then, O(n) otherwise.
 */
function updateCommitGraph(previous: CommitGraph | undefined, commits: readonly Commit[]): CommitGraph {
  if (!previous || commits.length < previous.size) return createCommitGraph(commits)
  const state = graphState.get(previous)
  if (!state) return createCommitGraph(commits)
  const old = previous.commits
  for (let row = 0; row < previous.size; row += 1) {
    if (!sameShape(old[row] as Commit, commits[row] as Commit)) return createCommitGraph(commits)
  }
  if (commits.length === previous.size) {
    const next = { ...previous, commits }
    graphState.set(next, state)
    return next
  }
  return nest({ ...previous, commits }, { claims: new Map(state.claims), stack: [...state.stack] }, previous.size)
}

/**
 * The row of a commit id. Appending shares the index between graph versions, so an entry is checked against
 * this version's rows rather than trusted.
 */
function rowOfCommit(graph: CommitGraph, id: string) {
  const row = graph.rowOf.get(id)
  return row !== undefined && row < graph.size && graph.commits[row]?.id === id ? row : undefined
}

function isMergeRow(graph: CommitGraph, row: number) {
  return (graph.children[row] ?? 0) > 0
}

type VisibleRows = {
  /** Rows that show, in order. */
  readonly rows: Int32Array
  readonly count: number
  /** 1 where a row shows. */
  readonly shown: Uint8Array
  /** Where a shown row sits among the shown rows, -1 for a hidden one. */
  readonly position: Int32Array
}

/**
 * The rows that show with `expanded` merges open: a collapsed merge hides its whole block, and so does a row
 * `skip` leaves out, like another branch's commits while one is in focus. O(shown rows).
 */
function visibleRows(graph: CommitGraph, expanded: ReadonlySet<string>, skip?: (row: number) => boolean): VisibleRows {
  const rows = new Int32Array(graph.size)
  const shown = new Uint8Array(graph.size)
  const position = new Int32Array(graph.size).fill(-1)
  let count = 0
  let row = 0
  while (row < graph.size) {
    if (skip?.(row)) {
      row = graph.end[row] as number
      continue
    }
    rows[count] = row
    shown[row] = 1
    position[row] = count
    count += 1
    const commit = graph.commits[row] as Commit
    row = isMergeRow(graph, row) && !expanded.has(commit.id) ? (graph.end[row] as number) : row + 1
  }
  return { rows: rows.subarray(0, count), count, shown, position }
}

/** Every merge with a nested block, for "expand all". */
function mergeIds(graph: CommitGraph) {
  const ids: string[] = []
  for (let row = 0; row < graph.size; row += 1) {
    if (isMergeRow(graph, row)) ids.push((graph.commits[row] as Commit).id)
  }
  return ids
}

export { createCommitGraph, isMergeRow, mergeIds, rowOfCommit, updateCommitGraph, visibleRows }
export type {
  Commit,
  CommitAuthor,
  CommitGraph,
  CommitMessageSegment,
  CommitStats,
  CommitStatus,
  CommitTag,
  VisibleRows,
}

import { rowOfCommit, type Commit, type CommitGraph, type VisibleRows } from "@/lib/commit-graph"

/**
 * One row of the graph, `git log --graph` style, as it's drawn: only the first `maxLanes` lanes are. `lane` is the
 * column of the row's node. Between the top of the row and its node, each lane in `into` runs into the node;
 * between the node and the bottom, the node runs out to each lane in `out`; every lane in `through` passes
 * straight by. `width` counts the lanes the row draws.
 */
type LaneRow = {
  lane: number
  width: number
  into: readonly number[]
  out: readonly number[]
  through: readonly number[]
  /** Lanes past `maxLanes` that run through the row, not drawn: the "+N" beside the graph. */
  hidden: number
  /** The node's own lane is past `maxLanes`: it's drawn in the "+N" column. */
  nodeHidden: boolean
  /** Each drawn lane's tag at the top of the row and at its bottom, like a branch's colour. */
  tagsTop: readonly number[]
  tagsBottom: readonly number[]
  /** The node's tag. */
  tag: number
}

type LaneLayoutOptions = {
  /** Lanes drawn; the rest are counted in `hidden`. Default 12. */
  maxLanes?: number
  /** Commits whose lanes open before the first row, in this order: lane 0 for the base branch's head. */
  reserve?: readonly { id: string; tag: number }[]
  /**
   * A first parent stays in the commit's lane even when another lane expects it too, so each line keeps its lane
   * down to where they meet, as a branch does down to its merge-base. Off, a line joins the lane that expects its
   * parent at once, as `git log --graph` draws it.
   */
  keepLanes?: boolean
  /** The tag of a lane a commit opens as a head (no child shown above it), like its branch's colour. Default 0. */
  headTag?: (commit: Commit) => number | undefined
}

type LaneLayout = {
  readonly count: number
  /** The row at a shown position, computing the rows above it first, once. */
  at: (position: number) => LaneRow
}

const NONE: readonly number[] = []

/** Free lane indexes, smallest first; entries a lane has taken since are skipped as they come up. */
function createFreeLanes() {
  const heap: number[] = []
  const push = (lane: number) => {
    heap.push(lane)
    for (let at = heap.length - 1; at > 0;) {
      const parent = (at - 1) >> 1
      if ((heap[parent] as number) <= (heap[at] as number)) break
      ;[heap[parent], heap[at]] = [heap[at] as number, heap[parent] as number]
      at = parent
    }
  }
  const pop = () => {
    const top = heap[0] as number
    const last = heap.pop() as number
    if (heap.length > 0) {
      heap[0] = last
      for (let at = 0; ;) {
        const left = at * 2 + 1
        const right = left + 1
        let smallest = at
        if (left < heap.length && (heap[left] as number) < (heap[smallest] as number)) smallest = left
        if (right < heap.length && (heap[right] as number) < (heap[smallest] as number)) smallest = right
        if (smallest === at) break
        ;[heap[smallest], heap[at]] = [heap[at] as number, heap[smallest] as number]
        at = smallest
      }
    }
    return top
  }
  return {
    push,
    /** The smallest free lane at `from` or after, else `fallback` (a new lane at the end). */
    take(lanes: readonly (string | null)[], from: number, fallback: number) {
      while (heap.length > 0) {
        const lane = heap[0] as number
        if (lane >= lanes.length || lanes[lane] !== null) {
          pop()
          continue
        }
        if (lane < from) return fallback
        return pop()
      }
      return fallback
    },
  }
}

/**
 * Lays out the shown rows lazily, a scan from the top kept as it goes. A parent hidden in a collapsed merge draws
 * no edge; one not loaded yet keeps its lane open. A row costs O(maxLanes + parents) however many lanes are open:
 * commits find their lanes through an index, free lanes come off a heap, lanes past `maxLanes` are only counted.
 */
function createLaneLayout(graph: CommitGraph, visible: VisibleRows, options: LaneLayoutOptions = {}): LaneLayout {
  const maxLanes = Math.max(1, options.maxLanes ?? 12)
  const keepLanes = options.keepLanes ?? false
  const lanes: (string | null)[] = []
  const tags: number[] = []
  const expecting = new Map<string, number[]>()
  const free = createFreeLanes()
  let beyond = 0
  const done: LaneRow[] = []

  const set = (lane: number, id: string | null, tag = 0) => {
    const before = lanes[lane] ?? null
    if (before !== null) {
      const list = expecting.get(before)
      if (list) {
        const at = list.indexOf(lane)
        if (at >= 0) list.splice(at, 1)
        if (list.length === 0) expecting.delete(before)
      }
    }
    if (lane === lanes.length) lanes.push(null)
    if (lane >= maxLanes && (before === null) !== (id === null)) beyond += id === null ? -1 : 1
    lanes[lane] = id
    if (id === null) {
      free.push(lane)
      return
    }
    tags[lane] = tag
    const list = expecting.get(id)
    if (list) list.push(lane)
    else expecting.set(id, [lane])
  }

  for (const { id, tag } of options.reserve ?? []) set(lanes.length, id, tag)

  const hiddenRow = (id: string) => {
    const row = rowOfCommit(graph, id)
    return row !== undefined && visible.shown[row] === 0
  }

  const drawn = () => Math.min(lanes.length, maxLanes)

  const step = (commit: Commit): LaneRow => {
    const into = [...(expecting.get(commit.id) ?? NONE)].toSorted((a, b) => a - b)
    const top = drawn()
    const tagsTop = tags.slice(0, top)
    const through: number[] = []
    for (let lane = 0; lane < top; lane += 1) {
      const expected = lanes[lane]
      if (expected !== null && expected !== commit.id) through.push(lane)
    }
    const hiddenTop = beyond
    const node = into.length > 0 ? (into[0] as number) : free.take(lanes, 0, lanes.length)
    const tag = into.length > 0 ? (tags[node] as number) : (options.headTag?.(commit) ?? 0)
    for (const lane of into) set(lane, null)
    if (node === lanes.length) lanes.push(null)

    const out: number[] = []
    let first = true
    for (const parent of commit.parents) {
      if (hiddenRow(parent)) continue
      const existing = expecting.get(parent)?.[0]
      if (first && lanes[node] === null && (existing === undefined || keepLanes)) {
        set(node, parent, tag)
        out.push(node)
      } else if (existing !== undefined) {
        out.push(existing)
      } else {
        const lane = free.take(lanes, node + 1, lanes.length)
        set(lane, parent, tag)
        out.push(lane)
      }
      first = false
    }
    if (lanes[node] === null) free.push(node)

    const bottom = drawn()
    const width = Math.min(maxLanes, Math.max(top, bottom, node + 1))
    const hidden = Math.max(hiddenTop, beyond)
    while (lanes.length > 0 && lanes.at(-1) === null) lanes.pop()
    const shownOnly = (list: readonly number[]) => {
      const kept = list.filter((lane) => lane < maxLanes)
      return kept.length > 0 ? kept : NONE
    }
    return {
      lane: Math.min(node, maxLanes),
      width,
      into: shownOnly(into),
      out: shownOnly(out),
      through: through.length > 0 ? through : NONE,
      hidden,
      nodeHidden: node >= maxLanes,
      tagsTop,
      tagsBottom: tags.slice(0, bottom),
      tag,
    }
  }

  return {
    count: visible.count,
    at(position) {
      if (position < 0 || position >= visible.count) throw new RangeError(`No shown row ${String(position)}`)
      while (done.length <= position) {
        const row = visible.rows[done.length] as number
        done.push(step(graph.commits[row] as Commit))
      }
      return done[position] as LaneRow
    },
  }
}

export { createLaneLayout }
export type { LaneLayout, LaneLayoutOptions, LaneRow }

import { isMergeRow, rowOfCommit, type Commit, type CommitGraph, type CommitMessageSegment } from "@/lib/commit-graph"

// Git's own merge subjects: "Merge branch 'a' into b", "Merge a into b", "Merge pull request #1 from a/b".
const mergeSubject = /^Merge (?:(?:remote-tracking )?branch(?:es)? )?'?([\w./@-]+)'?(?: of \S+)? into '?([\w./@-]+)'?$/
const pullSubject = /^(Merge pull request #\d+ from )([\w./@-]+)$/
const ticks = /`([^`\n]+)`/g

function looksLikePath(text: string) {
  return /[/\\]/.test(text) || /\.[a-z0-9]{1,8}$/i.test(text)
}

function backticked(text: string): CommitMessageSegment {
  if (text.startsWith("branch:")) return { type: "branch", name: text.slice("branch:".length) }
  return looksLikePath(text) ? { type: "file", path: text } : { type: "code", text }
}

function pushText(segments: CommitMessageSegment[], text: string) {
  if (text !== "") segments.push({ type: "text", text })
}

/**
 * Splits a subject line into segments: a backticked path becomes a file chip, `` `branch:name` `` a branch chip,
 * other backticked text inline code, and git's merge subjects ("Merge a into b") branch chips.
 */
function parseCommitMessage(message: string): CommitMessageSegment[] {
  const merge = mergeSubject.exec(message)
  if (merge) {
    const [, from = "", into = ""] = merge
    return [
      { type: "text", text: "Merge " },
      { type: "branch", name: from },
      { type: "text", text: " into " },
      { type: "branch", name: into },
    ]
  }
  const pull = pullSubject.exec(message)
  if (pull)
    return [
      { type: "text", text: pull[1] ?? "" },
      { type: "branch", name: pull[2] ?? "" },
    ]
  const segments: CommitMessageSegment[] = []
  let last = 0
  for (const match of message.matchAll(ticks)) {
    pushText(segments, message.slice(last, match.index))
    segments.push(backticked(match[1] ?? ""))
    last = match.index + match[0].length
  }
  pushText(segments, message.slice(last))
  return segments
}

function segmentsOf(commit: Pick<Commit, "message">): readonly CommitMessageSegment[] {
  return typeof commit.message === "string" ? parseCommitMessage(commit.message) : commit.message
}

function segmentText(segment: CommitMessageSegment) {
  switch (segment.type) {
    case "file":
      return segment.path
    case "branch":
      return segment.name
    default:
      return segment.text
  }
}

/** The subject in the pieces a row shows it in: each segment's text, chips as their names, for find in page. */
const pieces = new WeakMap<object, readonly string[]>()

function subjectPieces(commit: Pick<Commit, "message">): readonly string[] {
  // Find in page asks for every row's pieces when it builds and again as rows scroll; parse each message once.
  let found = pieces.get(commit)
  if (!found) {
    found = segmentsOf(commit).map(segmentText)
    pieces.set(commit, found)
  }
  return found
}

/** The subject as plain text, chips read as their names: what typeahead, agents and find in page match. */
function commitSubject(commit: Pick<Commit, "message">) {
  if (typeof commit.message === "string") return commit.message.replaceAll(/`(?:branch:)?([^`\n]+)`/g, "$1")
  return commit.message.map(segmentText).join("")
}

type CommitMatch = { id: string; hash: string; subject: string; merge: boolean }

const subjectKey = (text: string) => text.trim().toLocaleLowerCase()

/**
 * Finds a commit by id, exact subject (any case) or a hash prefix of 4 or more characters. The subject index is
 * built on the first lookup that needs it, so a history no one searches never pays for it.
 */
function createCommitFinder(graph: CommitGraph): (ref: string) => CommitMatch | undefined {
  let subjects: Map<string, number> | undefined
  const match = (row: number): CommitMatch => {
    const commit = graph.commits[row] as Commit
    const hash = commit.hash ?? commit.id.slice(0, 7)
    return { id: commit.id, hash, subject: commitSubject(commit), merge: isMergeRow(graph, row) }
  }
  return (ref) => {
    const exact = rowOfCommit(graph, ref)
    if (exact !== undefined) return match(exact)
    if (!subjects) {
      subjects = new Map()
      for (let row = 0; row < graph.size; row += 1) {
        const key = subjectKey(commitSubject(graph.commits[row] as Commit))
        if (!subjects.has(key)) subjects.set(key, row)
      }
    }
    const bySubject = subjects.get(subjectKey(ref))
    if (bySubject !== undefined) return match(bySubject)
    if (ref.length < 4) return undefined
    for (let row = 0; row < graph.size; row += 1) {
      const commit = graph.commits[row] as Commit
      if (commit.id.startsWith(ref) || commit.hash?.startsWith(ref)) return match(row)
    }
    return undefined
  }
}

export { commitSubject, createCommitFinder, parseCommitMessage, segmentsOf, subjectPieces }
export type { CommitMatch }

import { rowOfCommit, type Commit, type CommitAuthor, type CommitGraph } from "@/lib/commit-graph"
import { toTime, type Instant } from "@/lib/time"
import type { Tone } from "@/lib/tone"

/** A branch and where its head is; `ahead` and `behind` against the base are worked out when they're missing. */
type CommitBranch = {
  name: string
  /** The id of the commit the branch points at. */
  head: string
  /** Colours its lane and pill instead of the colour its name picks. */
  tone?: Tone
  ahead?: number
  behind?: number
  updatedAt?: Instant
  author?: CommitAuthor
}

type BranchState = "base" | "active" | "merged" | "stale"

type BranchInfo = {
  name: string
  head: string
  ahead: number
  behind: number
  updatedAt: Instant | undefined
  author: CommitAuthor | undefined
  tone: Tone | undefined
  /** The lane colour: 0 for the base, 1–5 the categorical chart colours, 10 and up a tone. */
  tag: number
  /** Where it forked from the base's first-parent line, when that is loaded. */
  mergeBase: string | undefined
  state: BranchState
}

type BranchModel = {
  base: BranchInfo | undefined
  /** Branches beside the base that aren't merged into it, newest update first. */
  active: readonly BranchInfo[]
  all: readonly BranchInfo[]
  /** The branches whose head is a commit, by commit id. */
  byHead: ReadonlyMap<string, readonly BranchInfo[]>
  /** For a row, the index in `active` of the branch it's ahead of the base on, or -1. */
  owner: Int32Array
}

const TONES: readonly Tone[] = ["neutral", "info", "success", "warning", "destructive", "violet"]

/** The same name always gets the same of the five chart colours. */
function nameTag(name: string) {
  let hash = 0
  for (let at = 0; at < name.length; at += 1) hash = (hash * 31 + name.charCodeAt(at)) >>> 0
  return 1 + (hash % 5)
}

function tagOf(branch: Pick<CommitBranch, "name" | "tone">) {
  return branch.tone ? 10 + TONES.indexOf(branch.tone) : nameTag(branch.name)
}

type BranchModelOptions = {
  /** The base branch's name; its head's first-parent line is what others are ahead of or behind. */
  base: string | undefined
  /** A branch with no update for this long, in ms, is stale. Default 30 days. */
  staleAfter?: number
  now?: Instant
}

/**
 * Where each branch stands against the base, in one pass over the base's first-parent line and one walk down
 * each branch's first parents until it meets that line: O(commits + commits ahead).
 */
function createBranchModel(
  graph: CommitGraph,
  branches: readonly CommitBranch[],
  options: BranchModelOptions,
): BranchModel {
  const baseBranch = branches.find((branch) => branch.name === options.base)
  const onBase = new Int32Array(graph.size).fill(-1)
  const baseHead = baseBranch ? rowOfCommit(graph, baseBranch.head) : undefined
  let steps = 0
  for (let row = baseHead; row !== undefined;) {
    if (onBase[row] !== -1) break
    onBase[row] = steps
    steps += 1
    const parent = graph.commits[row]?.parents[0]
    row = parent === undefined ? undefined : rowOfCommit(graph, parent)
  }

  const now = options.now === undefined ? Date.now() : toTime(options.now)
  const staleAfter = options.staleAfter ?? 30 * 24 * 60 * 60 * 1000
  const owner = new Int32Array(graph.size).fill(-1)
  const all: BranchInfo[] = []
  const active: BranchInfo[] = []
  const pending: { info: BranchInfo; rows: number[] }[] = []

  for (const branch of branches) {
    const head = rowOfCommit(graph, branch.head)
    const rows: number[] = []
    let mergeBase: number | undefined
    for (let row = head; row !== undefined;) {
      if (onBase[row] !== -1) {
        mergeBase = row
        break
      }
      rows.push(row)
      const parent = graph.commits[row]?.parents[0]
      row = parent === undefined ? undefined : rowOfCommit(graph, parent)
    }
    const headCommit = head === undefined ? undefined : (graph.commits[head] as Commit)
    const updatedAt = branch.updatedAt ?? headCommit?.date
    const merged = head !== undefined && (graph.depth[head] ?? 0) > 0
    const stale = updatedAt !== undefined && now - toTime(updatedAt) > staleAfter
    const isBase = branch === baseBranch
    const info: BranchInfo = {
      name: branch.name,
      head: branch.head,
      ahead: branch.ahead ?? (isBase ? 0 : rows.length),
      behind: branch.behind ?? (isBase || mergeBase === undefined ? 0 : (onBase[mergeBase] as number)),
      updatedAt,
      author: branch.author ?? headCommit?.author,
      tone: branch.tone,
      tag: isBase ? 0 : tagOf(branch),
      mergeBase: mergeBase === undefined ? undefined : (graph.commits[mergeBase] as Commit).id,
      state: isBase ? "base" : merged ? "merged" : stale ? "stale" : "active",
    }
    all.push(info)
    if (info.state === "active" || info.state === "stale") pending.push({ info, rows })
  }

  // Five colours for any number of branches: each takes its name's, or the next one no other branch has yet, in
  // name order, so the same branches keep the same colours and up to five never share one.
  const taken = new Set<number>()
  for (const { info } of pending.toSorted((a, b) => (a.info.name < b.info.name ? -1 : 1))) {
    if (info.tone) continue
    let tag = info.tag
    for (let step = 0; step < 5 && taken.has(tag); step += 1) tag = (tag % 5) + 1
    info.tag = tag
    taken.add(tag)
  }
  pending.sort((a, b) => toTime(b.info.updatedAt ?? 0) - toTime(a.info.updatedAt ?? 0))
  for (const { info, rows } of pending) {
    const index = active.push(info) - 1
    for (const row of rows) if (owner[row] === -1) owner[row] = index
  }

  const byHead = new Map<string, BranchInfo[]>()
  for (const info of all) {
    const list = byHead.get(info.head)
    if (list) list.push(info)
    else byHead.set(info.head, [info])
  }
  return { base: all.find((info) => info.state === "base"), active, all, byHead, owner }
}

/** The tag a head commit's lane takes: the first branch pointing at it, else the base's. */
function headTagOf(model: BranchModel) {
  return (commit: Commit) => model.byHead.get(commit.id)?.[0]?.tag
}

export { createBranchModel, headTagOf, TONES as branchTones }
export type { BranchInfo, BranchModel, BranchModelOptions, BranchState, CommitBranch }
